"""Original mini-course authoring source. Existing lesson IDs are retained."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
courses=[]
def course(unit,title,goal):
 c=dict(id=unit+'-words',unitId=unit,level='A1',title=title,goal=goal,steps=[],examples=[],guided=[],independent=[],summary={});courses.append(c);return c
def step(c,title,introduction,rule,usage,structure,mistake,memory,table=None):
 d=dict(id=c['id']+'-teach-'+str(len(c['steps'])+1),title=title,introduction=introduction,rule=rule,usage=usage,structure=structure,mistake=mistake,memory=memory)
 if table:d['table']=table
 c['steps'].append(d)
def example(c,de,tr,explanation,highlights):
 c['examples'].append(dict(id=c['id']+'-example-'+str(len(c['examples'])+1),de=de,tr=tr,explanation=explanation,highlights=highlights))
def q(c,section,kind,prompt,answer,explanation,rule,word,options=(),tiles=None,accepted=None,notes=None,hints=None):
 i=len(c[section])+1;id=c['id']+'-'+section+'-'+str(i)
 opts=list(options)
 if opts:
  offset=i%len(opts);opts=opts[offset:]+opts[:offset]
 d=dict(id=id,type=kind,wordIds=[word],prompt=prompt,options=opts,accepted=accepted or [answer],explanation=explanation,rule=rule,hints=hints or [rule],kindLabel={'choice':'Seç ve açıkla','tr-de':'Çevir / tamamla','blank':'Boşluğu tamamla','sentence':'Cümleyi kur'}[kind])
 if tiles:d['tiles']=tiles
 if notes:d['optionNotes']=notes
 c[section].append(d)

c=course('a1-01','Selamlaşma ve Tanışma','Birini uygun biçimde selamla; adını, yaşadığın yeri ve nasıl olduğunu kısa bir konuşmada anlat.')
step(c,'1 · Günün saatine göre merhaba','Bir konuşmaya başlamak için uzun cümle kurman gerekmez. Önce duruma uygun bir selam seç.','Hallo günlük ve genellikle samimi bir selamdır. Guten Morgen sabah, Guten Tag gün içinde, Guten Abend akşam kullanılır. Bu selamları bütün olarak öğren.','Bir dükkânda Guten Tag, sabah sınıfta Guten Morgen diyebilirsin. Gute Nacht ise genellikle ayrılırken veya yatmadan önce söylenir.','Guten + Morgen / Tag / Abend; yatarken: Gute Nacht.','Guten Nacht değil, Gute Nacht. Guten Abend ile Gute Nacht aynı bağlamda kullanılmaz.','Akşam biriyle karşılaş: Guten Abend. Uykuya hazırlan: Gute Nacht.',{'heading':'Zaman ve durum seç','rows':[['sabah','Guten Morgen!','Günaydın!'],['gün içinde','Guten Tag!','İyi günler!'],['akşam karşılaşırken','Guten Abend!','İyi akşamlar!'],['yatarken / gece vedası','Gute Nacht!','İyi geceler!']]})
step(c,'2 · Ben ve sen: heißen','Türkçede “Adım Elif” deriz. Almancada aynı düşünceyi bir fiille kurabiliriz: heißen, adı olmak.','Ich ile heiße, du ile heißt kullanılır. Türkçeden farklı olarak özneyi genellikle açıkça söyle: Ich heiße Elif.','Birinin adını samimi biçimde sormak için Wie heißt du? de. İsim yerine Ich bin Elif de kullanılabilir.','Bildirme: Ich + heiße + ad. Soru: Wie + heißt + du?','Ich heißt yanlış; ich öznesi heiße ister. “Wie du heißt?” burada bağımsız soru sırası değildir.','Ich: sonu -e. Du: heißen fiilinde heißt; ayrıca bir s daha ekleme.',{'heading':'Özneye dokun, biçimi fark et','rows':[['ich','heiße','benim adım…'],['du','heißt','senin adın…'],['er / sie','heißt','onun adı…'],['Sie','heißen','sizin adınız… (resmî)']]})
step(c,'3 · du mu, Sie mi?','Almancada konuştuğun kişiye göre hitap biçimi değişir. Yeni tanıştığın yetişkinle resmî başlamak güvenli bir seçimdir.','du samimi tekil hitaptır. Sie resmî hitaptır ve büyük S ile yazılır. Wie heißen Sie? sorusunda fiil heißen olur.','Arkadaşınla Wie heißt du?; bir görevliyle Wie heißen Sie? kullan. Resmî Sie hem bir kişiye hem birden fazla kişiye yöneltilebilir.','Samimi: Wie heißt du? / Resmî: Wie heißen Sie?','Küçük harfli sie cümle içinde “o (kadın)” veya “onlar” olabilir. Resmî Sie her yerde büyük yazılır.','Büyük S: saygılı hitap. Hitabı değiştirirsen fiili de kontrol et.',{'heading':'Aynı amacı iki yolla söyle','rows':[['arkadaş','Wie heißt du?','Adın ne?'],['resmî görüşme','Wie heißen Sie?','Adınız ne?'],['arkadaş','Wie geht es dir?','Nasılsın?'],['resmî görüşme','Wie geht es Ihnen?','Nasılsınız?']]})
step(c,'4 · Nerede, nereden, nasıl?','Tanışmayı adından sonra iki küçük bilgiyle sürdürebilirsin: nerede yaşadığın ve nereden geldiğin.','Ich wohne in Berlin yaşadığın yeri; Ich komme aus Ankara geldiğin yeri anlatır. Wo nerede, woher nereden demektir. Wie geht es dir? bir hâl hatır sorusudur.','Bu derste şehir adlarıyla in ve aus kullanıyoruz. Ülke adlarının artikel kuralları ayrı bir konudur; örneğin aus der Türkei farklı bir yapıdır.','Wo wohnst du? → Ich wohne in Berlin. Woher kommst du? → Ich komme aus Ankara.','Woher wohnst du? bu anlamda uygun değildir: ikamet yeri için wo, köken için woher seç.','in bir noktanın içinde yaşamayı; aus çıkış noktasını hatırlatsın. ch ve w seslerini ses kaydından dinle: Almanca w, çoğunlukla Türkçedeki v sesine yakındır.')
